/* TU rva 0x5f280..0x5f390, 2 rows — generated by tools/regroup.py plan */
/* w40H @GRPAttackingObj@4 @ 0x5f280 v2 — short param used directly as
 * 16-bit (FA mov si,cx), bit=1 kept as a variable (FA keeps it in ebp,
 * SIB [ebp*4 + _groupIds], and masks with test [eax+1],ebp — the word
 * index is bit*2 of the ushort view of _groupIds). */
extern unsigned short curIdW;         /* -> _curId */
extern unsigned short groupIdsW[];    /* -> _groupIds */
extern unsigned char groupSizesB[];   /* -> _groupSizes */
extern unsigned char __stdcall GRPPartW(unsigned short id, long *out, long z);
extern long __fastcall OBJGetW(unsigned short w);

long __fastcall w40h5f280(short id)
{
	long grp, i, n, bit;
	char *o;

	if (!GRPPartW(curIdW, &grp, 0))
		return 0;
	n = 0;
	bit = 1;
	for (i = 0; (long)groupSizesB[grp] > i; i++) {
		o = (char *)OBJGetW(((unsigned short *)groupIdsW)[2 * bit]);
		if (*(long *)(o + 1) & bit)
			if (*(unsigned char *)(o + 0xe3) == 0x20 &&
			    *(unsigned short *)(o + 0xee) == (unsigned short)id)
				n++;
	}
	return n;
}

/* @GRPHumansFirst@4 rva 0x5f310, 128 B, no tail pad (c3 at 0x7f).
 * fastcall ecx=g, fpo: sub esp,4 / xor edx,edx (i) / push ebx,esi,edi /
 * mov bl,[gsizes+g] / push ebp / cmp bl,dl; je ret /
 * lea eax,[ecx+ecx*4] lea esi,[eax*2] (10g) / xor eax,eax; mov al,bl; mov [slot],eax (saved) /
 * do { lea eax,[esi+edx]; mov di,[eax*2+gids] (sel); lea ebx,[eax*2+gids] (p);
 *      mov eax,edi; and eax,0xffff; mov ebp,[eax*4+objPtrs] (op);
 *      mov al,[ebp+0x10]; test al,0x80; jskip;
 *      mov eax,edx; test edx,edx; jle skiploop;
 *      shift loop: mov bp,[ebx-2]; sub ebx,2; mov [ebx+2],bp; dec eax; jne;
 *      lea eax,[ecx*4]; mov [eax+eax*4+gids],di (gids[10g]=sel);
 *      inc edx; mov eax,[slot]; cmp edx,eax; jl loop; } epilogue pops+ret */
extern unsigned char w38d_gsizesX[];
extern unsigned short w38d_gidsX[];
extern long w38d_opsX[];

void __fastcall GRPHumansFirst(int g)
{
    unsigned short sel;
    unsigned short *p;
    long op;
    int i, saved, t;
    unsigned char count;

    i = 0;
    count = w38d_gsizesX[g];
    if (!count)
        return;
    saved = count;
    do {
        sel = w38d_gidsX[g * 10 + i];
        p = &w38d_gidsX[g * 10 + i];
        op = w38d_opsX[sel & 0xffff];
        if (*(unsigned char *)(op + 0x10) & 0x80) {
            for (t = i; t > 0; t--) {
                *p = *(p - 1);
                p--;
            }
            w38d_gidsX[g * 10] = sel;
        }
        i++;
    } while (i < saved);
}

